mapper.select:
SELECT CAST(line.id AS CHAR) AS id, line.line_name AS name, line.platform_value AS platform, COALESCE(line.delivery_url, '') AS deliveryUrl FROM pm_agency_line line INNER JOIN pm_project p ON p.id = line.project_id AND p.deleted_at = 0 WHERE line.project_id = #{projectId} AND line.deleted_at = 0
AND EXISTS ( SELECT 1 FROM sys_user scope_user INNER JOIN sys_department scope_department ON scope_department.id = scope_user.primary_department_id AND scope_department.deleted_at = 0 INNER JOIN sys_user creator_user ON creator_user.id = p.created_by INNER JOIN sys_department creator_department ON creator_department.id = creator_user.primary_department_id AND creator_department.deleted_at = 0 WHERE scope_user.id = #{scopeUserId} AND scope_user.deleted_at = 0 AND creator_department.path LIKE CONCAT(scope_department.path, '%') )
ORDER BY line.updated_at DESC, line.id DESC LIMIT #{limit}

SELECT FROM pm_project p WHERE p.deleted_at = 0
AND (p.project_code LIKE CONCAT('%', #{keyword}, '%') OR p.project_name LIKE CONCAT('%', #{keyword}, '%') OR p.product_info LIKE CONCAT('%', #{keyword}, '%'))
AND p.status = #{status}
AND EXISTS ( SELECT 1 FROM pm_project_platform pp WHERE pp.project_id = p.id AND pp.platform_value = #{platform} AND pp.deleted_at = 0 )
AND ( p.delivery_leader_id = #{scopeUserId} OR EXISTS ( SELECT 1 FROM sys_user scope_user INNER JOIN sys_department scope_department ON scope_department.id = scope_user.primary_department_id AND scope_department.deleted_at = 0 INNER JOIN sys_user creator_user ON creator_user.id = p.created_by INNER JOIN sys_department creator_department ON creator_department.id = creator_user.primary_department_id AND creator_department.deleted_at = 0 WHERE scope_user.id = #{scopeUserId} AND scope_user.deleted_at = 0 AND creator_department.path LIKE CONCAT(scope_department.path, '%') ) )
ORDER BY p.updated_at DESC, p.id DESC LIMIT #{offset}, #{pageSize}

mapper.update:
UPDATE pm_project
SET wallet_customer_ref_id = #{walletCustomerRefId}
WHERE id = #{id}
  AND deleted_at = 0
  AND (wallet_customer_ref_id IS NULL
    OR wallet_customer_ref_id = #{walletCustomerRefId})

