INSERT INTO pm_project_region (
    project_id, region_code, region_name, country_code, country_name, created_by
) VALUES (
    #{projectId}, #{regionCountry.regionCode}, #{regionCountry.regionName},
    #{regionCountry.countryCode}, #{regionCountry.countryName}, #{createdBy}
)

INSERT INTO pm_project_kpi (
    project_id, metric_value, comparator, target_value, target_max_value, sort_order,
    created_by, updated_by
) VALUES (
    #{projectId}, #{metric}, #{comparator}, #{target}, #{targetMax}, #{sortOrder},
    #{operatorId}, #{operatorId}
)

INSERT INTO pm_agency_line (
    project_id, request_id, line_name, platform_value, delivery_type, delivery_url,
    page_id, pixel_name, pixel_id, token_ciphertext, test_code, cloak_url,
    optimizer_id, optimizer_name, created_by, updated_by
) VALUES (
    #{projectId}, #{requestId}, #{lineName}, #{platformValue}, #{type}, #{deliveryUrl},
    #{pageId}, #{pixelName}, #{pixelId}, #{tokenCiphertext}, #{testCode}, #{cloakUrl},
    #{optimizerId}, #{optimizerName}, #{createdBy}, #{updatedBy}
)

INSERT INTO pm_agency_line_delivery_url_history (
    agency_line_id, version_no, delivery_url, changed_by, changed_by_name
) VALUES (
    #{agencyLineId}, #{versionNo}, #{deliveryUrl}, #{changedBy}, #{changedByName}
)

